-- Table structures of the older people-management-service system (as of the date this file was made), used to test the exporter.
-- Foreign keys are left out so a test can seed in any order.
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `people`;
CREATE TABLE `people` (
  `id` int NOT NULL AUTO_INCREMENT,
  `organisation_id` int NOT NULL,
  `person_type` enum('staff','person_we_support') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'staff',
  `user_id` int DEFAULT NULL,
  `first_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `employee_reference` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nhs_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_approval_status` enum('approved','pending','rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'approved',
  `photo_pending_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_org_employee_ref` (`organisation_id`,`employee_reference`),
  KEY `idx_organisation` (`organisation_id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_person_type` (`person_type`),
  KEY `idx_employee_reference` (`employee_reference`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_profiles`;
CREATE TABLE `staff_profiles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `person_id` int NOT NULL,
  `job_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employment_start_date` date DEFAULT NULL,
  `employment_end_date` date DEFAULT NULL,
  `line_manager_id` int DEFAULT NULL,
  `emergency_contact_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergency_contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `ni_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'National Insurance number (UK)',
  `bank_sort_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Bank sort code',
  `bank_account_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Bank account number',
  `bank_account_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Account holder name',
  `address_line1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Address line 1',
  `address_line2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Address line 2',
  `address_city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'City/Town',
  `address_county` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'County/State',
  `address_postcode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Postcode/ZIP',
  `address_country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'United Kingdom' COMMENT 'Country',
  `contracted_hours` decimal(5,2) DEFAULT NULL COMMENT 'Contracted hours per week',
  `place_of_work` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Primary place of work/location',
  `job_description_id` int DEFAULT NULL COMMENT 'Reference to job_descriptions table',
  `external_job_description_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL to job description in external system',
  `external_job_description_ref` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reference ID for job description in external system',
  `job_post_id` int DEFAULT NULL COMMENT 'Reference to job_posts table',
  `is_tupe` tinyint(1) DEFAULT '0' COMMENT 'Whether this staff member has a TUPE contract',
  `tupe_transfer_date` date DEFAULT NULL COMMENT 'Date of TUPE transfer',
  `tupe_previous_organisation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Previous organisation name',
  `tupe_previous_employer_ref` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reference/ID from previous employer',
  `tupe_contract_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Contract type under TUPE (overrides job post)',
  `tupe_hours_per_week` decimal(5,2) DEFAULT NULL COMMENT 'Hours per week under TUPE (overrides job post)',
  `tupe_salary` decimal(10,2) DEFAULT NULL COMMENT 'Salary under TUPE (overrides job post)',
  `tupe_salary_currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'GBP' COMMENT 'Currency for TUPE salary',
  `tupe_notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Additional TUPE-related notes',
  `wtd_agreed` tinyint(1) DEFAULT '0' COMMENT 'Whether staff member has agreed to Working Time Directive',
  `wtd_agreement_date` date DEFAULT NULL COMMENT 'Date when WTD agreement was signed',
  `wtd_agreement_version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Version of WTD agreement document',
  `wtd_opt_out` tinyint(1) DEFAULT '0' COMMENT 'Whether staff member has opted out of 48-hour week limit',
  `wtd_opt_out_date` date DEFAULT NULL COMMENT 'Date when opt-out was signed',
  `wtd_opt_out_expiry_date` date DEFAULT NULL COMMENT 'Date when opt-out expires (if applicable)',
  `wtd_notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Additional notes about WTD agreement',
  `annual_leave_allocation` decimal(5,2) DEFAULT NULL COMMENT 'Annual leave allocation in days from job post',
  `annual_leave_used` decimal(5,2) DEFAULT '0.00' COMMENT 'Annual leave used in days',
  `annual_leave_carry_over` decimal(5,2) DEFAULT '0.00' COMMENT 'Annual leave carried over from previous year',
  `time_in_lieu_hours` decimal(5,2) DEFAULT '0.00' COMMENT 'Time in lieu hours accrued',
  `time_in_lieu_used` decimal(5,2) DEFAULT '0.00' COMMENT 'Time in lieu hours used',
  `lying_time_hours` decimal(5,2) DEFAULT '0.00' COMMENT 'Lying time hours accrued',
  `lying_time_used` decimal(5,2) DEFAULT '0.00' COMMENT 'Lying time hours used',
  `leave_year_start_date` date DEFAULT NULL COMMENT 'Start date of current leave year',
  `leave_year_end_date` date DEFAULT NULL COMMENT 'End date of current leave year',
  `contract_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Contract type: permanent, fixed_term, zero_hours, bank, apprentice, agency, etc.',
  `is_bank_staff` tinyint(1) DEFAULT '0' COMMENT 'Indicates if staff member is bank/casual staff',
  `is_apprentice` tinyint(1) DEFAULT '0' COMMENT 'Indicates if staff member is an apprentice',
  `has_visa` tinyint(1) DEFAULT '0' COMMENT 'Indicates if staff member requires a visa',
  `visa_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Type of visa (e.g., Tier 2, Skilled Worker, etc.)',
  `visa_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Visa reference number',
  `visa_issue_date` date DEFAULT NULL COMMENT 'Visa issue date',
  `visa_expiry_date` date DEFAULT NULL COMMENT 'Visa expiry date',
  `visa_sponsor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Visa sponsor organisation',
  `apprenticeship_start_date` date DEFAULT NULL COMMENT 'Apprenticeship start date',
  `apprenticeship_end_date` date DEFAULT NULL COMMENT 'Apprenticeship expected end date',
  `apprenticeship_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Apprenticeship level (e.g., Level 2, Level 3, etc.)',
  `apprenticeship_provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Apprenticeship training provider',
  `signature_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path to uploaded signature image file',
  `signature_created_at` datetime DEFAULT NULL COMMENT 'When the signature was created/uploaded',
  `signature_method` enum('upload','digital') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Method used to create signature (upload or digital drawing)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_person` (`person_id`),
  KEY `idx_line_manager` (`line_manager_id`),
  KEY `idx_ni_number` (`ni_number`),
  KEY `fk_job_post` (`job_post_id`),
  KEY `idx_is_tupe` (`is_tupe`),
  KEY `idx_wtd_agreed` (`wtd_agreed`),
  KEY `idx_wtd_opt_out` (`wtd_opt_out`),
  KEY `idx_wtd_opt_out_expiry` (`wtd_opt_out_expiry_date`),
  KEY `idx_leave_year` (`leave_year_start_date`,`leave_year_end_date`),
  KEY `idx_contract_type` (`contract_type`),
  KEY `idx_bank_staff` (`is_bank_staff`),
  KEY `idx_visa_expiry` (`visa_expiry_date`),
  KEY `idx_apprenticeship` (`is_apprentice`),
  KEY `idx_signature_path` (`signature_path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_registrations`;
CREATE TABLE `staff_registrations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `person_id` int NOT NULL COMMENT 'Reference to staff_profiles.person_id',
  `organisation_id` int NOT NULL COMMENT 'Reference to organisations.id',
  `registration_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of registration (e.g., Social Services, HCPC, NMC, etc.)',
  `registration_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Registration number or reference',
  `registration_body` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Issuing body (e.g., Social Care Wales, HCPC, etc.)',
  `issue_date` date DEFAULT NULL COMMENT 'Date registration was issued',
  `expiry_date` date NOT NULL COMMENT 'Date registration expires',
  `renewal_date` date DEFAULT NULL COMMENT 'Date registration should be renewed',
  `renewal_submitted_at` date DEFAULT NULL COMMENT 'Date the renewal was submitted to the registering body',
  `is_active` tinyint(1) DEFAULT '1' COMMENT 'Whether this registration is currently active',
  `is_required_for_role` tinyint(1) DEFAULT '1' COMMENT 'Whether this registration is required for their role',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Additional notes about the registration',
  `document_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path to uploaded registration document',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_person_id` (`person_id`),
  KEY `idx_organisation_id` (`organisation_id`),
  KEY `idx_expiry_date` (`expiry_date`),
  KEY `idx_registration_type` (`registration_type`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks professional registrations and certifications for staff members';

DROP TABLE IF EXISTS `staff_supervisions`;
CREATE TABLE `staff_supervisions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `person_id` int NOT NULL,
  `organisation_id` int NOT NULL,
  `supervision_date` date NOT NULL,
  `due_date` date DEFAULT NULL,
  `supervisor_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supervisor_person_id` int DEFAULT NULL,
  `supervision_type` enum('individual','group','peer','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'individual',
  `duration_minutes` int DEFAULT NULL,
  `outcome` text COLLATE utf8mb4_unicode_ci,
  `next_due_date` date DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_supervisions_person` (`person_id`),
  KEY `idx_supervisions_org` (`organisation_id`),
  KEY `idx_supervisions_next_due` (`next_due_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_appraisals`;
CREATE TABLE `staff_appraisals` (
  `id` int NOT NULL AUTO_INCREMENT,
  `person_id` int NOT NULL,
  `organisation_id` int NOT NULL,
  `appraisal_date` date NOT NULL,
  `due_date` date DEFAULT NULL,
  `appraiser_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `appraiser_person_id` int DEFAULT NULL,
  `appraisal_type` enum('annual','probationary','interim','return_to_work','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'annual',
  `outcome` enum('outstanding','exceeds_expectations','meets_expectations','requires_improvement','unsatisfactory','not_completed','pending') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `next_due_date` date DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_appraisals_person` (`person_id`),
  KEY `idx_appraisals_org` (`organisation_id`),
  KEY `idx_appraisals_next_due` (`next_due_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_learning_records`;
CREATE TABLE `staff_learning_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `person_id` int NOT NULL COMMENT 'Reference to people.id',
  `organisation_id` int NOT NULL COMMENT 'Reference to organisations.id',
  `record_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type: qualification, course, training, certification, etc.',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Title of qualification/course/learning',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Description of the learning/qualification',
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Provider/institution (e.g., university, training company)',
  `qualification_level` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Level (e.g., Level 2, Level 3, Degree, Masters)',
  `subject_area` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Subject or field of study',
  `completion_date` date DEFAULT NULL COMMENT 'Date completed/achieved',
  `expiry_date` date DEFAULT NULL COMMENT 'Expiry date if applicable (e.g., for certifications)',
  `grade` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Grade or result achieved',
  `credits` decimal(5,2) DEFAULT NULL COMMENT 'Credits or hours (if applicable)',
  `certificate_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Certificate or qualification number',
  `certificate_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path to uploaded certificate document',
  `external_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL to external record (e.g., LMS link)',
  `source_system` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Source system: recruitment, lms, hr, manual',
  `external_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'External ID from source system',
  `is_mandatory` tinyint(1) DEFAULT '0' COMMENT 'Whether this is mandatory training',
  `is_required_for_role` tinyint(1) DEFAULT '0' COMMENT 'Whether required for their current role',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'completed' COMMENT 'Status: completed, in_progress, expired, pending',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Additional notes',
  `created_by` int DEFAULT NULL COMMENT 'User who created this record',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_synced_at` timestamp NULL DEFAULT NULL COMMENT 'Last time synced from external system',
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_person_id` (`person_id`),
  KEY `idx_organisation_id` (`organisation_id`),
  KEY `idx_record_type` (`record_type`),
  KEY `idx_completion_date` (`completion_date`),
  KEY `idx_expiry_date` (`expiry_date`),
  KEY `idx_status` (`status`),
  KEY `idx_source_system` (`source_system`),
  KEY `idx_external_id` (`external_id`),
  KEY `idx_is_mandatory` (`is_mandatory`),
  KEY `idx_org_person` (`organisation_id`,`person_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks qualifications and learning records for staff members, including from recruitment, LMS, and manual entries';

DROP TABLE IF EXISTS `staff_role_history`;
CREATE TABLE `staff_role_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `person_id` int NOT NULL COMMENT 'Reference to people.id',
  `organisation_id` int NOT NULL COMMENT 'Reference to organisations.id',
  `job_post_id` int DEFAULT NULL COMMENT 'Reference to job_posts.id - the role/position',
  `job_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Job title (can be different from job_post title if customized)',
  `start_date` date NOT NULL COMMENT 'Date role started',
  `end_date` date DEFAULT NULL COMMENT 'Date role ended (NULL if current role)',
  `is_current` tinyint(1) DEFAULT '0' COMMENT 'Whether this is the current active role',
  `salary` decimal(10,2) DEFAULT NULL COMMENT 'Salary for this role',
  `salary_currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'GBP' COMMENT 'Salary currency',
  `hours_per_week` decimal(5,2) DEFAULT NULL COMMENT 'Hours per week for this role',
  `contract_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Contract type for this role',
  `line_manager_id` int DEFAULT NULL COMMENT 'Line manager for this role',
  `place_of_work` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Place of work for this role',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Notes about this role assignment',
  `created_by` int DEFAULT NULL COMMENT 'User who created this record',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `line_manager_id` (`line_manager_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_person_id` (`person_id`),
  KEY `idx_organisation_id` (`organisation_id`),
  KEY `idx_job_post_id` (`job_post_id`),
  KEY `idx_start_date` (`start_date`),
  KEY `idx_end_date` (`end_date`),
  KEY `idx_is_current` (`is_current`),
  KEY `idx_dates` (`start_date`,`end_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks role history and salary changes for staff members over time';

